  story:[{h:"הילד שהרג את סביו",t:"אדמונד קמפר גדל בבית שבו אמו, קלארנל, השפילה אותו באופן שיטתי. בגיל צעיר הוא נשלח לישון במרתף. בגיל 12 הוא נשלח לגור אצל סבו וסבתו בחווה מבודדת בצפון קליפורניה.<br><br>ב־<b>27 באוגוסט 1964</b>, בגיל 15, הוא ירה למוות בסבתו מוד ואז חיכה לסבו אדמונד סניור וירה בו גם. אחר כך הוא התקשר לאמו וסיפר לה מה עשה. כששאלו אותו למה, הוא ענה שרצה לדעת <em>איך זה מרגיש</em>."},{h:"שוחרר ביום הולדתו",t:"הוא נשלח לבית החולים הפסיכיאטרי באטסקדרו. שם, לפי עדותו, הוא למד לענות נכון על מבחנים פסיכולוגיים — ואף עזר לצוות לנהל אותם.<br><br>ב־<b>18 בדצמבר 1969</b>, ביום הולדתו ה־21, הוא שוחרר. נגד המלצת הפסיכיאטרים, הוא הוחזר לחזקת אמו. הרישום הפלילי שלו נמחק."},{h:"הטרמפיסטיות",t:"בין מאי 1972 לפברואר 1973 הוא אסף שש נשים צעירות שנסעו בטרמפים באזור סנטה קרוז. הרכב שלו, ההופעה השקטה שלו והתו של אמו על השמשה — שאפשר כניסה לקמפוס — עשו אותו לא מאיים.<br><br>העיתונות קראה לו <b>\"רוצח הקו־אדיות\"</b>. אף אחד לא חיפש גבר בן 24 ששותה בירה עם שוטרים בבר שליד תחנת המשטרה — כי הוא באמת עשה את זה, והם חיבבו אותו."},{h:"אמא",t:"ב־<b>20 באפריל 1973</b> הוא רצח את אמו קלארנל. למחרת הוא הזמין את חברתה של אמו, שרה הלט, לארוחת ערב, ורצח גם אותה.<br><br>ואז הוא נסע מזרחה, וחיכה. כשהחדשות לא דיווחו כלום, הוא עצר בטלפון ציבורי בקולורדו והתקשר למשטרת סנטה קרוז כדי להסגיר את עצמו. השוטר בקו לא האמין לו. הוא נאלץ להתקשר שוב."},{h:"הראיונות",t:"בכלא קמפר הפך לאחד המרואיינים המשמעותיים ביותר של יחידת מדעי ההתנהגות של ה־FBI. רוברט רסלר וג׳ון דאגלס ראיינו אותו שעות ארוכות.<br><br>הניתוח המילולי, המדויק והשקול שהוא נתן על מניעיו — <b>תרם ישירות לפיתוח שיטת הפרופיילינג ההתנהגותי</b> שתשמש בעשורים הבאים. אחד מהמרואיינים הכי משתפי פעולה שהיו למערכת, ואחד מהמפחידים ביותר."}],
  quotes:[{t:"רציתי לדעת איך זה מרגיש לירות בסבתא.",by:"אד קמפר",role:"על רצח סביו ב־1964"},{t:"מה שאתה חושב עליי כשאתה שוכב במיטה בלילה — זה בדיוק מה שאני.",by:"אד קמפר",role:""},{t:"החברה שלי הייתה במיטה שלי, וזו הייתה אמא שלי.",by:"אד קמפר",role:"בראיון בכלא"},{t:"חלק מזה היה לגלות מה הופך אותי לכזה.",by:"אד קמפר",role:"על שיתוף הפעולה שלו עם ה־FBI"},{t:"הוא ידע בדיוק מה הוא עושה. זה מה שהופך אותו לכל כך שימושי — וכל כך מפחיד.",by:"מתוך תיעוד יחידת מדעי ההתנהגות",role:"כפי שדווח"},{t:"הסיבה היחידה שהפסיק הייתה מיוזמתו שלו.",by:"מאיה גזית",role:"מהפוסט על הפרק"}],
