  story:[{h:"ילדות שלא הייתה",t:"אמה של איילין נטשה אותה ואת אחיה כשהייתה בת ארבע. הם גדלו אצל סבה וסבתה במישיגן, בבית שתואר כאלים ומתעלל. אביה הביולוגי, שאותו לא הכירה, היה עבריין מין מורשע שהתאבד בכלא.<br><br>בגיל 11 היא כבר סחרה במין תמורת סיגריות ואוכל. <b>בגיל 14 היא נאנסה ונכנסה להריון.</b> התינוק נמסר לאימוץ. בגיל 15 היא הושלכה מהבית וחיה ביערות סמוכים."},{h:"טיריה",t:"ב־1986 היא פגשה את <b>טיריה מור</b>, עובדת ניקיון במוטל. הן חיו יחד כחמש שנים. איילין פרנסה את שתיהן מזנות בכבישים המהירים של פלורידה.<br><br>מערכת היחסים הזאת היא ציר מרכזי בתיק — ובסופו של דבר גם מה שסגר אותו: מור שיתפה פעולה עם החוקרים בתמורה לחסינות, והקליטה שיחות טלפון שבהן הובילה את איילין להודות."},{h:"שבעה גברים",t:"בין נובמבר 1989 לנובמבר 1990 נמצאו שבעה גברים יריים למוות בפלורידה. כולם היו לקוחות או נהגים שאספו אותה. כולם נורו מאקדח .22.<br><br>וורנוס טענה לאורך כל הדרך ש<b>מלורי, הראשון, אנס אותה</b> ושהיא ירתה בהגנה עצמית. לגבי השאר הגרסאות שלה השתנו לאורך השנים — לפעמים הגנה עצמית, לפעמים לא.<br><br><b>הערת הארכיון:</b> בבדיקה מאוחרת התברר שלריצ׳רד מלורי אכן הייתה הרשעה קודמת בעבירת מין. העובדה הזאת לא הוצגה למושבעים במשפט."},{h:"התעשייה שנבנתה סביבה",t:"עוד לפני שהמשפט הסתיים, זכויות הסיפור כבר נמכרו. <b>שלושה שוטרים</b> ממחוז מריון נחקרו בחשד שניסו למכור את סיפורה. בת זוגה שיתפה פעולה עם התביעה. עורכי דין, מפיקים ופוליטיקאים מצאו עניין בתיק.<br><br>זה החלק שמאיה הדגישה בפוסט: <em>לא ברור מי נבזי יותר.</em>"},{h:"הסוף",t:"ב־2001 וורנוס ביקשה בעצמה להפסיק את הערעורים ולהיות מוצאת להורג. היא הצהירה שהיא הורגת שוב אם תשוחרר.<br><br>ב־<b>9 באוקטובר 2002</b> היא הוצאה להורג בזריקה קלטלנית. מותה נקבע ב־9:47 בבוקר."}],
  quotes:[{t:"לא ברור מי נבזי יותר: איילין או אלו שסבבו אותה.",by:"מאיה גזית",role:"מהפוסט על הפרק"},{t:"אני שטה עם הסלע, ואחזור, כמו ביום העצמאות, עם ישו.",by:"איילין וורנוס",role:"מילותיה האחרונות, 9 באוקטובר 2002"},{t:"הרוצחות הסדרתיות נחשבות ל\"רוצחות השקטות\". איילין לא עונה על אף אחד מהמאפיינים.",by:"מאיה גזית",role:"מהפוסט"},{t:"בכל חייה היה רק אומללות, בגידה וניצול.",by:"מאיה גזית",role:"מהפוסט"},{t:"הרשעתו הקודמת של מלורי בעבירת מין לא הוצגה למושבעים.",by:"הערת הארכיון",role:"עובדה מתועדת מהחקירה המאוחרת"}],
