  facts:[["פול ברנרדו","נולד 27 באוגוסט 1964, סקארבורו, אונטריו"],["קרלה הומולקה","נולדה 4 במאי 1970, פורט קרדיט, אונטריו"],["\"אנס סקארבורו\"","1986–1990 — לפחות 14 מקרי אונס ושישה ניסיונות מיוחסים לו"],["טאמי הומולקה","23 בדצמבר 1990, בת 15. סווג תחילה כמוות בתאונה משאיפת הקאה"],["לסלי מאהפי","נחטפה 15 ביוני 1991, בת 14. גופתה נמצאה 29 ביוני — יום חתונתם"],["קריסטן פרנץ׳","נחטפה 16 באפריל 1992, בת 15. נמצאה 30 באפריל"],["החתונה","29 ביוני 1991"],["עסקת הטיעון","נחתמה 14 במאי 1993 — 12 שנות מאסר לקרלה בתמורה לעדות"],["הקלטות","הוסתרו על ידי הסנגור 17 חודשים והועברו למשטרה רק אחרי חתימת העסקה"],["ברנרדו","הורשע 1 בספטמבר 1995. מאסר עולם והכרזה כעבריין מסוכן"],["קרלה","שוחררה ביולי 2005 לאחר ריצוי מלוא 12 השנים"]],
  story:[{h:"אנס סקארבורו",t:"בין 1986 ל־1990 פעל בפרברי טורונטו תוקף שכונה בעיתונות <b>\"אנס סקארבורו\"</b>. לפחות 14 מקרי אונס ושישה ניסיונות יוחסו לו.<br><br>ב־1990 נלקחה ממנו דגימת DNA כחלק ממאגר חשודים. <b>היא נשארה על מדף במעבדה שנתיים</b>, בלי שנבדקה, בזמן שהחקירה נמשכה במקביל.<br><br>שמו: פול ברנרדו. רואה חשבון בהכשרתו, בן טובים למראה."},{h:"טאמי",t:"ב־<b>23 בדצמבר 1990</b> מתה <b>טאמי הומולקה</b>, אחותה בת ה־15 של קרלה, בבית משפחתה.<br><br>הקביעה הרשמית: מוות בתאונה, שאיפת הקאה על רקע אלכוהול.<br><br>רק שנים אחר כך התברר מה קרה באותו לילה. טאמי לא נספרה כקורבן עד שהתגלו הקלטות."},{h:"החתונה",t:"ב־<b>15 ביוני 1991</b> נחטפה <b>לסלי מאהפי</b> בת ה־14 מבורלינגטון. היא נרצחה למחרת. גופתה הושלכה מבותרת ויצוקה בבטון באגם גיבסון.<br><br>ב־<b>29 ביוני 1991</b> נמצאו גושי הבטון.<br><br>באותו יום בדיוק, קרלה הומולקה ופול ברנרדו התחתנו. כרכרה לבנה, סוסים, שמלה לבנה."},{h:"קריסטן",t:"ב־<b>16 באפריל 1992</b>, סוף שבוע הפסחא, נחטפה <b>קריסטן פרנץ׳</b> בת ה־15 מסנט קתרינס. היא נרצחה למחרת ונמצאה ב־30 באפריל.<br><br>הפעם היו עדים לרכב. הציבור בקנדה כבר היה במתח מלא.<br><br>בפברואר 1993, אחרי שקרלה פנתה למשטרה על רקע אלימות במשפחה, החקירה התכנסה סוף סוף על ברנרדו."},{h:"העסקה והקלטות",t:"ב־<b>14 במאי 1993</b> נחתמה עסקת טיעון: קרלה הומולקה תרצה <b>12 שנה</b> בתמורה לעדות מלאה נגד בעלה. התביעה הציגה אותה כשותפה שנכפתה.<br><br>ואז נמצאו <b>הקלטות הווידאו</b>. הסנגור של ברנרדו, קן מארי, מצא אותן מוסתרות בגוף תאורה בתקרת חדר האמבטיה. הוא החזיק אותן <b>17 חודשים</b>. רק עורך דין שהחליף אותו העביר אותן למשטרה.<br><br>מה שנראה בהן שינה לחלוטין את התמונה — אבל <b>העסקה כבר נחתמה</b>. בקנדה קראו לה \"העסקה עם השטן\"."}],
  quotes:[{t:"מהצד החתונה נראתה כמו חלום. אבל באותו היום היה היום הכי קשה וקורע לב למשפחת מאהפי.",by:"מאיה גזית",role:"מהפוסט על הפרק"},{t:"דגימת ה־DNA שלו נשארה על מדף במעבדה שנתיים בלי שנבדקה.",by:"מתוך ועדת הבדיקה",role:"דו\"ח קמפבל, 1996"},{t:"הקלטות הוסתרו 17 חודשים — והגיעו למשטרה רק אחרי שהעסקה נחתמה.",by:"מתוך התיק המשפטי",role:""},{t:"בקנדה קראו לזה \"העסקה עם השטן\".",by:"מהשיח הציבורי בקנדה",role:"אחרי גילוי הקלטות"},{t:"הפנטזיות המיניות של פול ברנרדו וקרלה הומולקה הופכות למציאות.",by:"מאיה גזית",role:"מהפוסט על חלק ב"}],
  victims:[{n:1,name:"טאמי לין הומולקה",en:"Tammy Lyn Homolka",age:15, f:1, from:"סנט קתרינס, אונטריו",date:"23 בדצמבר 1990",county:"בית משפחת הומולקה",act:"אחותה של קרלה",d:"אחותה הצעירה של קרלה. מתה בבית המשפחה בערב חג המולד. הקביעה הרשמית בזמן אמת: <b>מוות בתאונה</b> משאיפת הקאה על רקע אלכוהול. רק שנים אחר כך, עם גילוי הקלטות, התברר מה קרה באותו לילה.",tags:["אחותה של קרלה","סווג כתאונה","לא נספרה בזמן אמת"],photos:["bernardo-tammy"]},
    {n:2,name:"לסלי אריקה מאהפי",en:"Leslie Erika Mahaffy",age:14, f:1, from:"בורלינגטון, אונטריו",date:"15–16 ביוני 1991",county:"אגם גיבסון",act:"נחטפה ליד ביתה",d:"ננעלה מחוץ לביתה בלילה. נחטפה ונרצחה למחרת. גופתה נמצאה ב־<b>29 ביוני 1991</b> — יום נישואיהם של ברנרדו והומולקה.",tags:["בת 14","נמצאה ביום חתונתם"],photos:["bernardo-leslie"]},
    {n:3,name:"קריסטן דון פרנץ׳",en:"Kristen Dawn French",age:15, f:1, from:"סנט קתרינס, אונטריו",date:"16–17 באפריל 1992",county:"ברלינגטון",act:"נחטפה בדרכה הביתה",d:"נחטפה בסוף שבוע הפסחא בדרכה הביתה מבית הספר. נמצאה ב־30 באפריל. הפעם היו עדי ראייה לרכב — נתון שהאיץ את החקירה.",tags:["בת 15","עדי ראייה לרכב","הקורבן האחרונה"],photos:["bernardo-kristen"]},
    {n:4,name:"נשות סקארבורו — ניצולות",en:"Scarborough Rapist survivors", f:1, from:"סקארבורו, אונטריו",date:"1986–1990",county:"פרברי טורונטו",act:"שרדו",d:"לפחות <b>14 נשים</b> שרדו תקיפות מין שיוחסו לברנרדו בין 1986 ל־1990, בנוסף לשישה ניסיונות. תיאוריהן היו מדויקים, והקלסתרון שהופק מהם דומה לו מאוד. הוא נשאר חופשי עוד שנתיים.",tags:["14 ניצולות","הקלסתרון","שנתיים נוספות"]}],
