  evidence:[{k:"addr",art:"prison",wide:true,t:"25 Cromwell Street",s:"ראיה 01",p:"הכתובת שנמחקה מהמפה.",b:"בית טורי צר בגלוסטר, עם מרתף וגינה קטנה. משפחת ווסט עברה אליו ב־1972.<br><br>הם השכירו חדרים לדיירות צעירות. הם גידלו שם שמונה ילדים.<br><br>ב־<b>1996</b>, אחרי המשפט, הבית נהרס עד היסוד. <b>כל החומרים נטחנו</b> כדי למנוע מזכרות. במקומו נסלל שביל הולכי רגל.<br><br>הכתובת נמחקה — הכתובות בסביבה מוספרו מחדש."},
    {k:"joke",art:"witness",wide:true,t:"הבדיחה",s:"ראיה 02",p:"המשפט שפתח את התיק.",b:"במשפחת ווסט הייתה בדיחה חוזרת. ילד שהתנהג לא יפה נענה שהוא יגמור <b>\"מתחת למרצפות, כמו הת׳ר\"</b>.<br><br>הילדים חזרו עליה גם מחוץ לבית.<br><br>ב־1992, במהלך חקירת התעללות נפרדת, שוטרת שמעה על הבדיחה. היא לא התעלמה ממנה.<br><br>שנתיים אחר כך המשטרה קיבלה <b>צו חפירה</b> לגינת הבית. הבדיחה הזאת היא הראיה הכי חשובה בתיק."},
    {k:"dig",art:"crate",t:"החפירה",s:"ראיה 03",p:"24–26 בפברואר 1994.",b:"ב־<b>24 בפברואר 1994</b> החלה משטרת גלוסטרשייר לחפור בגינה האחורית.<br><br>ב־<b>26 בפברואר</b> נמצאו השרידים הראשונים.<br><br>החפירות התרחבו: הגינה, המרתף, מתחת לרצפות, ובהמשך גם נכסים קודמים של המשפחה ושדה סמוך.<br><br><b>12 קורבנות ידועים</b> אותרו בסך הכל."},
    {k:"who",art:"users",img:"west-charmaine",wide:true,t:"למה איש לא חיפש",s:"ראיה 04",p:"נערות שהמערכת סימנה מראש.",b:"רוב הקורבנות היו נערות שברחו מהבית, דיירות זמניות, נערות ממוסדות סעד וטרמפיסטיות.<br><br>כשהן נעלמו, ההנחה המערכתית הייתה שהן <b>\"עזבו\"</b>. לא נפתחו חקירות רצח.<br><br>היוצאת מן הכלל: <b>לוסי פרטינגטון</b>, סטודנטית מאוניברסיטת אקסטר, שהגיעה ממשפחה שידעה לדרוש. היעלמותה כן נחקרה.<br><br>זו בדיוק ההערה של מאיה: <em>\"רצחו נערות עזובות ולאף אחד לא היה אכפת.\"</em>"},
    {k:"kids",art:"mother",img:"west-heather",t:"הבנות",s:"ראיה 05",p:"שרמיין והת׳ר.",b:"<b>שרמיין ווסט</b>, בת 8 — בתו של פרד מנישואיו הראשונים. נעלמה ביוני 1971, בזמן שפרד ריצה מאסר קצר. <b>רוז הייתה האחראית היחידה עליה.</b> האישום ברצח שלה הוגש נגד רוז רק אחרי מותו של פרד.<br><br><b>הת׳ר ווסט</b>, בת 16 — בתם המשותפת. נעלמה ב־19 ביוני 1987. ההורים סיפרו שברחה לוויילס.<br><br>שתי הבנות האלה הן גם הקורבנות וגם הראיות: אחת קבעה את אשמתה של רוז, השנייה פתחה את התיק."},
    {k:"end",art:"gavel",img:"west-rose",t:"שני סופים",s:"ראיה 06",p:"1 בינואר 1995 · נובמבר 1995.",b:"<b>פרד ווסט</b> התאבד בתא מעצרו בכלא ווינסון ב־<b>1 בינואר 1995</b>, לפני שהמשפט התחיל. הוא לא הועמד לדין מעולם.<br><br><b>רוז ווסט</b> עמדה למשפט לבדה. בנובמבר 1995 היא הורשעה ב<b>עשרה סעיפי רצח</b> ונדונה למאסר עולם. ב־2019 אושרה רשמית ההוראה שלא תשוחרר לעולם.<br><br>היא ממשיכה להכחיש כל מעורבות."}],
  host:{intro:"הפוסט של מאיה על הפרק.",items:[{k:"verdict",t:"זוג הרוצחים הפורה ביותר של בריטניה",d:"הפתיחה של מאיה — והדגש על משך הזמן שבו איש לא ראה.",q:"פרד ורוז ווסט היו זוג הרוצחים הסדרתיים הפוריים ביותר של בריטניה. הם חיו חיים אפלים ואלימים והפשעים הנוראים שלהם נעלמו מעיניהם של הרשויות במשך כמעט שני עשורים."},
    {k:"bts",t:"לגדל ילדים ולרצוח נערות",d:"הסתירה שמאיה מציבה במרכז: אותו בית, אותה תקופה, שתי מציאויות.",q:"לאורך שנות ה־70 וה־80 בעודם מרחיבים את המשפחה ומגדלים ילדים, הם ארבו לנערות ובחורות צעירות שחיו בשוליים ופיתו אותן לגור איתם בבית המשפחה ובכך חרצו את גורלן."},
    {k:"verdict",t:"המשפט שסוגר את הפוסט",d:"הזווית האמיתית של הפרק היא לא הרוצחים — אלא האדישות.",q:"זוג רוצחים סדרתיים שרצחו נערות עזובות ולאף אחד לא היה אכפת."}]},
