  facts:[["נולד","11 במאי 1954, שרלוט, צפון קרוליינה"],["רקע","גדל בפונטה גורדה, פלורידה. שירת בצי האמריקאי מ־1977"],["מקצוע","אח מעשי מוסמך מ־1995. סיים ראשון במחזור. עבד במרכז הרפואי של פונטה גורדה"],["מקום","מחוז שרלוט, דרום פלורידה"],["תקופה","1993–1996"],["הכינוי","\"Hog Trail Killer\" — על שם שבילי ציד חזירי הבר שבהם הושלכו הגופות"],["פרופיל הקורבנות","גברים בשוליים — חסרי בית, עובדי מין, מכורים. רבים נותרו אלמונים לשנים"],["ניצול","סטנלי ברדן, 1994 — נקשר לעץ וכמעט נחנק. שרד עם צלקות חבל"],["נעצר","3 ביולי 1996, על ניסיון רצח ברדן"],["הרשעה","17 באוגוסט 1999 — ברצח ריצ׳רד מונטגומרי בלבד"],["גזר דין","10 בדצמבר 1999 — עונש מוות"],["מרצה","Union Correctional Institution, ריפורד, פלורידה"]],
  story:[{h:"האזור הבטוח",t:"מחוז שרלוט בדרום פלורידה נחשב לאזור עם שיעור פשיעה נמוך — מקום שאנשים עברו אליו כדי לגדל ילדים.<br><br>ואז, מ־1994, התחילו למצוא ביערות גופות של גברים.<br><br>הם נמצאו בשבילים שבהם ציידים נהגו לצוד חזירי בר. מכאן הכינוי שדבק בתיק: <b>\"Hog Trail Killer\"</b>."},{h:"מי היו האלמונים",t:"רוב הקורבנות היו גברים בשולי החברה: חסרי בית, עובדי מין, מכורים, גברים שנעו בין מדינות.<br><br>כשגופה נמצאה, לא היה מי שידווח על היעלמות מקבילה. חלקם נותרו <b>\"ג׳ון דו\"</b> — אלמונים — במשך שנים ואף עשורים.<br><br><b>ג׳רלד לומברד</b> נמצא ב־1994 וזוהה רק ביוני <b>2021</b>. <b>אלחנדרו לאגו</b> נמצא ב־2002 וזוהה ביולי <b>2024</b>.<br><br>שבעה ועשרים שנה בין מציאת גופה לבין השבת שם."},{h:"הניצול",t:"ב־1994 גבר בשם <b>סטנלי ברדן</b> קיבל הצעה מקונהן, נלקח ליער, <b>נקשר לעץ וכמעט נחנק</b>.<br><br>הוא שרד. שנתיים לאחר מכן עדיין נראו על צווארו צלקות החבל.<br><br>עדותו היא הבסיס למעצרו של קונהן ב־<b>3 ביולי 1996</b> — לא על רצח, אלא על ניסיון רצח."},{h:"הרשעה אחת",t:"קונהן ויתר על מושבעים ובחר במשפט בפני שופט. המשפט נפתח ב־<b>9 באוגוסט 1999</b>.<br><br>ב־<b>17 באוגוסט</b>, אחרי דיון של 25 דקות, השופט ויליאם בלקוול הרשיע אותו ברצח מדרגה ראשונה ובחטיפה של <b>ריצ׳רד אלן מונטגומרי</b>, בן 21.<br><br>ב־10 בדצמבר 1999 נגזר עליו עונש מוות.<br><br><b>זו ההרשעה היחידה שלו.</b> כל שאר המקרים — עד תריסר — נותרו ברמת קישור חקירתי."},{h:"הזיהוי המאוחר",t:"ב־<b>23 במרץ 2007</b> נמצאו בפורט מאיירס שרידיהם של שמונה גברים — פרשה שנודעה כ\"שמונת פורט מאיירס\".<br><br>ארבעה זוהו לאורך השנים: ג׳ון בלווינס וארייק קולר ב־2007, ג׳ונתן טיהאי ב־2008, רוברט סודן ב־<b>2022</b>. ארבעה נותרו אלמונים.<br><br>ההתקדמות הגיעה מטכנולוגיות זיהוי שלא היו קיימות בזמן אמת — ובעבודה עקשנית של מומחים לרפואה משפטית. <b>זה החלק שמאיה הקדישה לו פוסט המשך נפרד בקבוצה.</b>"}],
  quotes:[{t:"תושבי מחוז שרלוט התחילו לגלות גופות של גברים אלמונים ביער.",by:"מאיה גזית",role:"מהפוסט על הפרק"},{t:"נהג להביא את הקורבנות שלו ליער בו ציידים נהגו לצוד חזירי בר.",by:"מאיה גזית",role:"מהפוסט"},{t:"שנתיים אחרי, עדיין נראו על צווארו צלקות החבל.",by:"מתוך תיעוד המקרה",role:"על סטנלי ברדן, הניצול"},{t:"השופט הרשיע אותו אחרי דיון של 25 דקות.",by:"מתוך פרוטוקול המשפט",role:"17 באוגוסט 1999"},{t:"ג׳רלד לומברד נמצא ב־1994 וזוהה ב־2021.",by:"מתוך תיעוד הזיהוי",role:"27 שנה"}],
