  facts:[["נולד","7 במרץ 1971, פלורידה"],["1986","בגיל 15 חטף ואנס נערה בת 14 בטמפה, אריזונה. הודה ב־1987 ונדון ל־15 שנה"],["שוחרר","אוגוסט 2001"],["רישיון תיווך","30 ביוני 2006 — הושג לאחר הצגה מטעה של הרשעתו"],["הקריירה","בנה משרד תיווך עם כתריסר סוכנים. דורג בין המובילים באזור"],["6 בנובמבר 2003","ירי בארבעה עובדי Superbike Motorsports בצ׳סני — תיק שנשאר לא פתור 13 שנה"],["דצמבר 2015","ג׳וני קוקסי ומייגן מקרו־קוקסי נעלמים"],["31 באוגוסט 2016","צ׳ארלס דיוויד קרוור נורה למוות בנכס שלו"],["3 בנובמבר 2016","קלה בראון נמצאת חיה, כבולה בתוך מכולת מתכת בנכס"],["הודאה","26 במאי 2017 — שבעה סעיפי רצח, שני סעיפי חטיפה ותקיפה מינית"],["גזר דין","שבעה מאסרי עולם ברצף, ללא אפשרות שחרור"]],
  story:[{h:"1986",t:"בגיל 15, בטמפה שבאריזונה, טוד קולהפ חטף נערה בת 14, איים עליה באקדח, לקח אותה לביתו, קשר אותה ואנס אותה.<br><br>הוא הודה ב־1987 ונדון ל<b>15 שנות מאסר</b>. הוא שוחרר באוגוסט 2001.<br><br>הוא היה עבריין מין רשום. זה לא מנע ממנו את מה שקרה אחר כך."},{h:"החנות",t:"ב־<b>6 בנובמבר 2003</b>, בחנות אופנועים בשם <b>Superbike Motorsports</b> בצ׳סני, דרום קרוליינה, נורו למוות ארבעה אנשים:<br><br><b>סקוט פונדר</b> (30), הבעלים · <b>בריאן לוקאס</b> (29), מנהל שירות · <b>כריס שרברט</b> (26), מכונאי · <b>בוורלי גאי</b> (52), מנהלת חשבונות ואמו של פונדר.<br><br>לא היו עדים. לא היה מניע ברור. <b>התיק נשאר לא פתור שלוש עשרה שנה.</b>"},{h:"הקריירה",t:"ב־2006 קיבל קולהפ רישיון תיווך נדל\"ן — לאחר שהציג את הרשעתו בצורה מטעה.<br><br>הוא בנה משרד עם כתריסר סוכנים ודורג בין המתווכים המובילים באזור. לקוחות תיארו אותו כאיש עסקים ממוקד.<br><br>במקביל הוא רכש שטח של כ־95 דונם בוודרוף. שם הוא הציב <b>מכולת מתכת</b>."},{h:"3 בנובמבר 2016",t:"<b>קלה בראון</b>, בת 30, ובן זוגה <b>צ׳ארלס דיוויד קרוור</b>, בן 32, נעלמו באוגוסט 2016 אחרי שיצאו לעבודת ניקיון בנכס.<br><br>חוקרים איתרו אות סלולרי אחרון באזור הנכס של קולהפ. ב־<b>3 בנובמבר 2016</b> הם הגיעו לשם.<br><br>הם שמעו דפיקות. קלה בראון נמצאה <b>חיה, כבולה בשרשרת לקיר בתוך מכולת מתכת</b>. היא הוחזקה שם כחודשיים.<br><br>היא סיפרה לחוקרים שקרוור נורה למוות מולה, ושקולהפ התוודה בפניה על ירי בחנות האופנועים ב־2003."},{h:"הביקורות",t:"אחרי המעצר, מישהו מצא את חשבון האמזון שלו.<br><br>קולהפ כתב ביקורות מוצרים תחת השם <b>\"me\"</b>. על את חפירה מתקפל: <i>\"רצוי להשאיר אותו כל הזמן במכונית שלכם, למקרה שאתם צריכים להחביא גופה, ואת החפירה הגדול להשאיר בבית.\"</i> על מנעולים ועל תחמושת — הערות באותו נוסח.<br><br>ב־<b>26 במאי 2017</b> הוא הודה ב<b>שבעה סעיפי רצח</b> בעסקת טיעון שמנעה עונש מוות, ונדון לשבעה מאסרי עולם ברצף."}],
  quotes:[{t:"החלום שלו להיות רוצח סדרתי עם מספר תלת ספרתי של קורבנות.",by:"מאיה גזית",role:"מהפוסט על הפרק"},{t:"רצוי להשאיר אותו כל הזמן במכונית שלכם, למקרה שאתם צריכים להחביא גופה.",by:"טוד קולהפ",role:"מביקורת על את חפירה מתקפל באמזון"},{t:"היא נמצאה חיה, כבולה בשרשרת לקיר בתוך מכולת מתכת.",by:"מתוך תיעוד החילוץ",role:"3 בנובמבר 2016"},{t:"התיק של חנות האופנועים נשאר לא פתור שלוש עשרה שנה.",by:"מתוך תיעוד התיק",role:""},{t:"מצד אחד ניתב את היכולות שלו לקריירה מצליחה, ומצד שני רצח ואנס.",by:"מאיה גזית",role:"מהפוסט"}],
