  evidence:[{k:"cont",art:"crate",wide:true,t:"המכולה",s:"ראיה 01",p:"חודשיים, שרשרת, קיר מתכת.",b:"בנכס של כ־95 דונם בוודרוף הוצבה <b>מכולת מתכת</b>.<br><br>בתוכה, כבולה בשרשרת לקיר, הוחזקה <b>קלה בראון</b> במשך כחודשיים.<br><br>ב־3 בנובמבר 2016 הגיעו חוקרים לנכס בעקבות איכון האות הסלולרי האחרון של בן זוגה. <b>הם שמעו דפיקות</b> מתוך המכולה.<br><br>היא נמצאה חיה."},
    {k:"amazon",art:"chat",wide:true,t:"הביקורות באמזון",s:"ראיה 02",p:"חשבון בשם \"me\".",b:"קולהפ כתב ביקורות מוצרים באמזון תחת השם <b>\"me\"</b>. אחרי מעצרו הן נקראו מחדש:<br><br>· על <b>את חפירה מתקפל</b>: <i>\"רצוי להשאיר אותו כל הזמן במכונית שלכם, למקרה שאתם צריכים להחביא גופה, ואת החפירה הגדול להשאיר בבית.\"</i><br>· על <b>מנעולים למכולות משא</b> ועל <b>תחמושת</b> — הערות באותו נוסח.<br><br>הביקורות היו <b>ציבוריות, בשם משתמש, במשך שנים</b>.<br><br>הן לא ראיה משפטית. הן דוגמה לכך שמידע יכול להיות גלוי לחלוטין — ובכל זאת בלתי נראה, עד שיודעים מה מחפשים."},
    {k:"superbike",art:"rifle",wide:true,t:"6 בנובמבר 2003",s:"ראיה 03",p:"שלוש עשרה שנים בלי קצה חוט.",b:"ארבעה עובדים נורו למוות בחנות האופנועים <b>Superbike Motorsports</b> בצ׳סני: סקוט פונדר, בריאן לוקאס, כריס שרברט ובוורלי גאי.<br><br>לא היו עדים. לא היה מניע ברור. לא נמצא חשוד.<br><br>התיק נשאר <b>פתוח 13 שנה</b> — עד שקלה בראון סיפרה לחוקרים שקולהפ התוודה בפניה עליו.<br><br>אחת מהמשפחות ניהלה במשך שנים קמפיין ציבורי לשמירת התיק פתוח."},
    {k:"license",art:"gavel",t:"רישיון התיווך",s:"ראיה 04",p:"עבריין מין רשום עם רישיון.",b:"ב־30 ביוני 2006 קיבל קולהפ <b>רישיון תיווך נדל\"ן</b> בדרום קרוליינה — לאחר שהציג את הרשעתו מ־1987 בצורה מטעה.<br><br>הוא היה <b>עבריין מין רשום</b>. הוא בנה משרד עם כתריסר סוכנים ודורג בין המובילים באזור.<br><br>הפער בין מערכת רישום עברייני המין לבין מערכת רישוי המקצועות הוא הנקודה המערכתית בתיק הזה."},
    {k:"brown",art:"witness",t:"העדות של קלה בראון",s:"ראיה 05",p:"מה שהיא סיפרה סגר תיק בן 13 שנה.",b:"אחרי חילוצה מסרה קלה בראון עדות מפורטת:<br><br>· <b>צ׳ארלס קרוור נורה למוות מולה</b><br>· היא הוחזקה במכולה כחודשיים<br>· <b>קולהפ התוודה בפניה</b> על הירי בחנות האופנועים ב־2003<br><br>העדות הזאת היא שהובילה לחיפושים בנכס, שבהם נמצאו שרידיהם של בני הזוג קוקסי — ולסגירת תיק Superbike אחרי 13 שנה."},
    {k:"deal",art:"scale",t:"שבעה מאסרי עולם",s:"ראיה 06",p:"26 במאי 2017.",b:"קולהפ הודה ב<b>שבעה סעיפי רצח</b>, בשני סעיפי חטיפה ובסעיף תקיפה מינית.<br><br>העסקה מנעה ממנו את עונש המוות. הוא נדון ל<b>שבעה מאסרי עולם ברצף</b>, ללא אפשרות שחרור.<br><br>לאחר גזר הדין הוא טען בהזדמנויות שונות לקורבנות נוספים. <b>אף אחת מהטענות האלה לא אומתה</b>, והוא לא הועמד לדין בגינן.<br><br>מאיה ציטטה בפוסט את הצהרתו על \"חלום\" למספר תלת ספרתי — כאמירה שלו, לא כעובדה."}],
  host:{intro:"הפוסט של מאיה על הפרק.",items:[{k:"verdict",t:"מאיפה הכינוי",d:"הפתיחה של מאיה — התחביב הביזארי שהפך לשם של התיק.",q:"טוד קולהפ, נקרא גם \"רוצח האמזון\" כי לאחר מעצרו התברר שלרוצח היה תחביב ביזארי להשאיר סקירות על מוצרים שונים באמזון… על את חפירה מתקפל שרכש הגיב \"רצוי להשאיר אותו כל הזמן במכונית שלכם, למקרה שאתם צריכים להחביא גופה ואת החפירה הגדול נשאר בבית\"."},
    {k:"verdict",t:"שני צדדים",d:"הפער שמאיה מציבה במרכז הפרק.",q:"הסיפור של טוד קולהפ הוא סיפור על רוצח שמצד אחד ניתב את היכולות שלו לקריירה מצליחה, ומצד שני רצח ואנס והיה זה שאמר שהחלום שלו להיות רוצח סדרתי עם מספר תלת ספרתי של קורבנות."},
    {k:"bts",t:"הערת דיוק של הארכיון",d:"ההצהרה על \"מספר תלת ספרתי\" היא אמירה של קולהפ עצמו, אחרי גזר הדין. היא לא אומתה ולא הובילה לאישומים נוספים. הארכיון מציג אותה כציטוט, לא כנתון."}]},
